using Microsoft.Data.SqlClient;
using System.Security.Claims;

public static class InventoryFeatures
{
    static bool Manager(ClaimsPrincipal u)=>new[]{"owner","manager"}.Contains(u.FindFirstValue(ClaimTypes.Role)??"");
    static Guid UserId(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);
    public static void MapInventoryFeatures(this WebApplication app,string db)
    {
        app.MapGet("/api/inventory/ingredients",async(ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand(@"SELECT i.Id,i.Code,i.Name,i.Category,i.Unit,i.Quantity,i.ReorderLevel,i.AverageCost,i.IsActive,
CASE WHEN i.Quantity<=i.ReorderLevel THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END,
ISNULL(STUFF((SELECT N', '+p.Name FROM dbo.RecipeComponents r JOIN dbo.Products p ON p.Id=r.ProductId WHERE r.IngredientId=i.Id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,2,N''),N'')
FROM dbo.Ingredients i WHERE i.IsActive=1 ORDER BY CASE WHEN i.Quantity<=i.ReorderLevel THEN 0 ELSE 1 END,i.Name",c);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),code=r.IsDBNull(1)?"":r.GetString(1),name=r.GetString(2),category=r.IsDBNull(3)?"":r.GetString(3),unit=r.GetString(4),quantity=r.GetDecimal(5),reorderLevel=r.GetDecimal(6),averageCost=r.GetDecimal(7),isActive=r.GetBoolean(8),lowStock=r.GetBoolean(9),affectedProducts=r.GetString(10)});return Results.Ok(rows);});
        app.MapPost("/api/inventory/ingredients",async(IngredientInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.Unit)||x.ReorderLevel<0)return Results.BadRequest(new{error="Thông tin nguyên liệu không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.Ingredients(StoreId,Code,Name,Category,Unit,Quantity,ReorderLevel,AverageCost)OUTPUT INSERTED.Id VALUES(@s,NULLIF(@code,''),@name,NULLIF(@category,''),@unit,0,@level,0)",c);q.Parameters.AddWithValue("@code",x.Code?.Trim()??"");q.Parameters.AddWithValue("@name",x.Name.Trim());q.Parameters.AddWithValue("@category",x.Category?.Trim()??"");q.Parameters.AddWithValue("@unit",x.Unit.Trim());q.Parameters.AddWithValue("@level",x.ReorderLevel);try{return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});}catch(SqlException){return Results.Conflict(new{error="Mã nguyên liệu đã tồn tại."});}});
        app.MapPatch("/api/inventory/ingredients/{id:guid}",async(Guid id,IngredientInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.Ingredients SET Code=NULLIF(@code,''),Name=@name,Category=NULLIF(@category,''),Unit=@unit,ReorderLevel=@level WHERE Id=@id",c);q.Parameters.AddWithValue("@id",id);q.Parameters.AddWithValue("@code",x.Code?.Trim()??"");q.Parameters.AddWithValue("@name",x.Name.Trim());q.Parameters.AddWithValue("@category",x.Category?.Trim()??"");q.Parameters.AddWithValue("@unit",x.Unit.Trim());q.Parameters.AddWithValue("@level",x.ReorderLevel);return await q.ExecuteNonQueryAsync()>0?Results.Ok(new{id}):Results.NotFound();});

        app.MapGet("/api/inventory/suppliers",async(ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("SELECT Id,Name,Phone,Address,Note FROM dbo.Suppliers WHERE IsActive=1 ORDER BY Name",c);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),name=r.GetString(1),phone=r.IsDBNull(2)?"":r.GetString(2),address=r.IsDBNull(3)?"":r.GetString(3),note=r.IsDBNull(4)?"":r.GetString(4)});return Results.Ok(rows);});
        app.MapPost("/api/inventory/suppliers",async(SupplierInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên nhà cung cấp không được trống."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.Suppliers(StoreId,Name,Phone,Address,Note)OUTPUT INSERTED.Id VALUES(@s,@name,NULLIF(@phone,''),NULLIF(@address,''),NULLIF(@note,''))",c);q.Parameters.AddWithValue("@name",x.Name.Trim());q.Parameters.AddWithValue("@phone",x.Phone?.Trim()??"");q.Parameters.AddWithValue("@address",x.Address?.Trim()??"");q.Parameters.AddWithValue("@note",x.Note?.Trim()??"");return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});

        app.MapGet("/api/inventory/receipts",async(ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("SELECT TOP 100 r.Id,r.ReceiptNumber,r.Status,r.TotalCost,r.CreatedAt,r.ConfirmedAt,ISNULL(s.Name,N'Không chọn NCC'),u.FullName,COUNT(i.Id) FROM dbo.StockReceipts r LEFT JOIN dbo.Suppliers s ON s.Id=r.SupplierId LEFT JOIN dbo.Users u ON u.Id=r.CreatedBy LEFT JOIN dbo.StockReceiptItems i ON i.ReceiptId=r.Id GROUP BY r.Id,r.ReceiptNumber,r.Status,r.TotalCost,r.CreatedAt,r.ConfirmedAt,s.Name,u.FullName ORDER BY r.CreatedAt DESC",c);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),receiptNumber=r.GetInt64(1),status=r.GetString(2),totalCost=r.GetDecimal(3),createdAt=r.GetDateTime(4),confirmedAt=r.IsDBNull(5)?(DateTime?)null:r.GetDateTime(5),supplier=r.GetString(6),createdBy=r.IsDBNull(7)?"":r.GetString(7),itemCount=r.GetInt32(8)});return Results.Ok(rows);});
        app.MapPost("/api/inventory/receipts",async(StockReceiptInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(x.Items.Count==0||x.Items.Any(i=>i.Quantity<=0||i.UnitCost<0))return Results.BadRequest(new{error="Phiếu nhập phải có nguyên liệu và số lượng hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{var id=Guid.NewGuid();var total=x.Items.Sum(i=>i.Quantity*i.UnitCost);await using(var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.StockReceipts(Id,StoreId,SupplierId,Note,TotalCost,CreatedBy)VALUES(@id,@s,@supplier,@note,@total,@user)",c,tx)){q.Parameters.AddWithValue("@id",id);q.Parameters.AddWithValue("@supplier",(object?)x.SupplierId??DBNull.Value);q.Parameters.AddWithValue("@note",(object?)x.Note?.Trim()??DBNull.Value);q.Parameters.AddWithValue("@total",total);q.Parameters.AddWithValue("@user",UserId(user));await q.ExecuteNonQueryAsync();}foreach(var item in x.Items){await using var q=new SqlCommand("INSERT dbo.StockReceiptItems(ReceiptId,IngredientId,Quantity,UnitCost)VALUES(@r,@i,@q,@cost)",c,tx);q.Parameters.AddWithValue("@r",id);q.Parameters.AddWithValue("@i",item.IngredientId);q.Parameters.AddWithValue("@q",item.Quantity);q.Parameters.AddWithValue("@cost",item.UnitCost);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();return Results.Ok(new{id,status="draft",totalCost=total});}catch(Exception e){await tx.RollbackAsync();return Results.BadRequest(new{error=e.Message});}});
        app.MapPost("/api/inventory/receipts/{id:guid}/confirm",async(Guid id,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();await using var lockReceipt=new SqlCommand("UPDATE dbo.StockReceipts SET Status='confirmed',ConfirmedBy=@u,ConfirmedAt=SYSUTCDATETIME() WHERE Id=@id AND Status='draft'",c,tx);lockReceipt.Parameters.AddWithValue("@u",UserId(user));lockReceipt.Parameters.AddWithValue("@id",id);if(await lockReceipt.ExecuteNonQueryAsync()==0){await tx.RollbackAsync();return Results.Conflict(new{error="Phiếu không tồn tại hoặc đã được xác nhận."});}await using var q=new SqlCommand(@"DECLARE @movement TABLE(IngredientId uniqueidentifier,Quantity decimal(18,3),UnitCost decimal(18,4));INSERT @movement SELECT IngredientId,Quantity,UnitCost FROM dbo.StockReceiptItems WHERE ReceiptId=@id;
UPDATE i SET AverageCost=CASE WHEN i.Quantity+m.Quantity=0 THEN i.AverageCost ELSE ((i.Quantity*i.AverageCost)+(m.Quantity*m.UnitCost))/(i.Quantity+m.Quantity) END,Quantity=i.Quantity+m.Quantity FROM dbo.Ingredients i JOIN @movement m ON m.IngredientId=i.Id;
INSERT dbo.StockMovements(IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,UnitCost,BalanceAfter) SELECT m.IngredientId,m.Quantity,N'Nhập kho phiếu #'+CONVERT(nvarchar(20),r.ReceiptNumber),@u,N'receipt',N'stock_receipt',@id,m.UnitCost,i.Quantity FROM @movement m JOIN dbo.Ingredients i ON i.Id=m.IngredientId JOIN dbo.StockReceipts r ON r.Id=@id;",c,tx);q.Parameters.AddWithValue("@id",id);q.Parameters.AddWithValue("@u",UserId(user));await q.ExecuteNonQueryAsync();await tx.CommitAsync();return Results.Ok(new{id,status="confirmed"});});

        app.MapGet("/api/inventory/recipes/{kind}/{id:guid}",async(string kind,Guid id,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(kind is not ("product" or "topping"))return Results.BadRequest(new{error="Loại công thức không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();var column=kind=="product"?"ProductId":"ToppingId";await using var q=new SqlCommand($"SELECT r.IngredientId,i.Name,i.Unit,r.Quantity,i.AverageCost FROM dbo.RecipeComponents r JOIN dbo.Ingredients i ON i.Id=r.IngredientId WHERE r.{column}=@id ORDER BY i.Name",c);q.Parameters.AddWithValue("@id",id);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{ingredientId=r.GetGuid(0),ingredient=r.GetString(1),unit=r.GetString(2),quantity=r.GetDecimal(3),estimatedCost=r.GetDecimal(3)*r.GetDecimal(4)});return Results.Ok(rows);});
        app.MapPut("/api/inventory/recipes/{kind}/{id:guid}",async(string kind,Guid id,RecipeInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(kind is not ("product" or "topping")||x.Items.Any(i=>i.Quantity<=0))return Results.BadRequest(new{error="Công thức không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var column=kind=="product"?"ProductId":"ToppingId";await using(var d=new SqlCommand($"DELETE dbo.RecipeComponents WHERE {column}=@id",c,tx)){d.Parameters.AddWithValue("@id",id);await d.ExecuteNonQueryAsync();}foreach(var item in x.Items){await using var q=new SqlCommand($"INSERT dbo.RecipeComponents({column},IngredientId,Quantity)VALUES(@owner,@ingredient,@quantity)",c,tx);q.Parameters.AddWithValue("@owner",id);q.Parameters.AddWithValue("@ingredient",item.IngredientId);q.Parameters.AddWithValue("@quantity",item.Quantity);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();return Results.Ok(new{id,kind,count=x.Items.Count});});

        app.MapPost("/api/inventory/adjustments",async(InventoryAdjustmentInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(x.QuantityChange==0||string.IsNullOrWhiteSpace(x.Reason))return Results.BadRequest(new{error="Nhập số lượng thay đổi và lý do."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();await using var q=new SqlCommand("UPDATE dbo.Ingredients SET Quantity=Quantity+@change WHERE Id=@id;INSERT dbo.StockMovements(IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,BalanceAfter)SELECT Id,@change,@reason,@user,@type,N'manual',NEWID(),Quantity FROM dbo.Ingredients WHERE Id=@id",c,tx);q.Parameters.AddWithValue("@change",x.QuantityChange);q.Parameters.AddWithValue("@id",x.IngredientId);q.Parameters.AddWithValue("@reason",x.Reason.Trim());q.Parameters.AddWithValue("@user",UserId(user));q.Parameters.AddWithValue("@type",x.QuantityChange<0?"waste":"adjustment");await q.ExecuteNonQueryAsync();await tx.CommitAsync();return Results.Ok(new{x.IngredientId,x.QuantityChange});});
        app.MapPost("/api/inventory/counts",async(InventoryCountInput x,ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();if(x.Items.Count==0)return Results.BadRequest(new{error="Phiếu kiểm kê chưa có nguyên liệu."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var countId=Guid.NewGuid();await using(var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.InventoryCounts(Id,StoreId,Note,CreatedBy)VALUES(@id,@s,@note,@u)",c,tx)){q.Parameters.AddWithValue("@id",countId);q.Parameters.AddWithValue("@note",(object?)x.Note??DBNull.Value);q.Parameters.AddWithValue("@u",UserId(user));await q.ExecuteNonQueryAsync();}foreach(var item in x.Items){await using var read=new SqlCommand("SELECT Quantity FROM dbo.Ingredients WHERE Id=@id",c,tx);read.Parameters.AddWithValue("@id",item.IngredientId);var system=Convert.ToDecimal(await read.ExecuteScalarAsync()??throw new InvalidOperationException("Nguyên liệu không tồn tại."));var diff=item.ActualQuantity-system;await using var q=new SqlCommand("INSERT dbo.InventoryCountItems(CountId,IngredientId,SystemQuantity,ActualQuantity,Difference)VALUES(@c,@i,@s,@a,@d);UPDATE dbo.Ingredients SET Quantity=@a WHERE Id=@i;INSERT dbo.StockMovements(IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,BalanceAfter)VALUES(@i,@d,N'Chênh lệch kiểm kê',@u,N'count',N'inventory_count',@c,@a)",c,tx);q.Parameters.AddWithValue("@c",countId);q.Parameters.AddWithValue("@i",item.IngredientId);q.Parameters.AddWithValue("@s",system);q.Parameters.AddWithValue("@a",item.ActualQuantity);q.Parameters.AddWithValue("@d",diff);q.Parameters.AddWithValue("@u",UserId(user));await q.ExecuteNonQueryAsync();}await tx.CommitAsync();return Results.Ok(new{id=countId});});
        app.MapGet("/api/inventory/report",async(ClaimsPrincipal user)=>{if(!Manager(user))return Results.Forbid();await using var c=new SqlConnection(db);await c.OpenAsync();var result=new Dictionary<string,object>();await using(var q=new SqlCommand("SELECT COUNT(*),SUM(CASE WHEN Quantity<=ReorderLevel THEN 1 ELSE 0 END),ISNULL(SUM(Quantity*AverageCost),0) FROM dbo.Ingredients WHERE IsActive=1",c)){await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();result["summary"]=new{ingredientCount=r.GetInt32(0),lowStockCount=r.IsDBNull(1)?0:r.GetInt32(1),stockValue=r.GetDecimal(2)};}await using(var q=new SqlCommand("SELECT TOP 100 m.Id,i.Name,i.Unit,m.QuantityChange,m.MovementType,m.Reason,m.BalanceAfter,m.CreatedAt,ISNULL(u.FullName,N'Hệ thống') FROM dbo.StockMovements m JOIN dbo.Ingredients i ON i.Id=m.IngredientId LEFT JOIN dbo.Users u ON u.Id=m.CreatedBy ORDER BY m.CreatedAt DESC",c)){await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),ingredient=r.GetString(1),unit=r.GetString(2),quantityChange=r.GetDecimal(3),type=r.GetString(4),reason=r.GetString(5),balanceAfter=r.IsDBNull(6)?(decimal?)null:r.GetDecimal(6),createdAt=r.GetDateTime(7),staff=r.GetString(8)});result["movements"]=rows;}await using(var q=new SqlCommand("SELECT ISNULL(SUM(CASE WHEN MovementType='waste' THEN ABS(QuantityChange)*ISNULL(UnitCost,i.AverageCost) ELSE 0 END),0),ISNULL(SUM(CASE WHEN MovementType='consumption' THEN ABS(QuantityChange)*ISNULL(UnitCost,i.AverageCost) ELSE 0 END),0) FROM dbo.StockMovements m JOIN dbo.Ingredients i ON i.Id=m.IngredientId",c)){await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();result["costs"]=new{wasteCost=r.GetDecimal(0),consumptionCost=r.GetDecimal(1)};}return Results.Ok(result);});
    }

    public static async Task DeductOrderItem(SqlConnection c,SqlTransaction tx,Guid itemId,Guid userId)
    {
        await using var claim=new SqlCommand("UPDATE dbo.OrderItems SET InventoryDeducted=1,InventoryDeductedAt=SYSUTCDATETIME() WHERE Id=@id AND InventoryDeducted=0 AND Status<>'cancelled'",c,tx);claim.Parameters.AddWithValue("@id",itemId);if(await claim.ExecuteNonQueryAsync()==0)return;
        await using var q=new SqlCommand(@";WITH Required AS(
SELECT rc.IngredientId,rc.Quantity*CONVERT(decimal(18,3),i.Quantity) Qty FROM dbo.OrderItems i JOIN dbo.RecipeComponents rc ON rc.ProductId=i.ProductId WHERE i.Id=@id
UNION ALL SELECT rc.IngredientId,rc.Quantity*CONVERT(decimal(18,3),i.Quantity)*CONVERT(decimal(18,3),t.Quantity) FROM dbo.OrderItems i JOIN dbo.OrderItemToppings t ON t.OrderItemId=i.Id JOIN dbo.RecipeComponents rc ON rc.ToppingId=t.ToppingId WHERE i.Id=@id), Totals AS(SELECT IngredientId,SUM(Qty) Qty FROM Required GROUP BY IngredientId)
UPDATE ing SET Quantity=Quantity-t.Qty FROM dbo.Ingredients ing JOIN Totals t ON t.IngredientId=ing.Id;
;WITH Required AS(SELECT rc.IngredientId,rc.Quantity*CONVERT(decimal(18,3),i.Quantity) Qty FROM dbo.OrderItems i JOIN dbo.RecipeComponents rc ON rc.ProductId=i.ProductId WHERE i.Id=@id UNION ALL SELECT rc.IngredientId,rc.Quantity*CONVERT(decimal(18,3),i.Quantity)*CONVERT(decimal(18,3),t.Quantity) FROM dbo.OrderItems i JOIN dbo.OrderItemToppings t ON t.OrderItemId=i.Id JOIN dbo.RecipeComponents rc ON rc.ToppingId=t.ToppingId WHERE i.Id=@id),Totals AS(SELECT IngredientId,SUM(Qty) Qty FROM Required GROUP BY IngredientId)
INSERT dbo.StockMovements(IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,UnitCost,BalanceAfter) SELECT t.IngredientId,-t.Qty,N'Trừ theo định lượng khi bắt đầu pha',@user,N'consumption',N'order_item',@id,i.AverageCost,i.Quantity FROM Totals t JOIN dbo.Ingredients i ON i.Id=t.IngredientId;",c,tx);q.Parameters.AddWithValue("@id",itemId);q.Parameters.AddWithValue("@user",userId);await q.ExecuteNonQueryAsync();
    }
    public static async Task DeductOrder(SqlConnection c,SqlTransaction tx,Guid orderId,Guid userId){await using var q=new SqlCommand("SELECT Id FROM dbo.OrderItems WHERE OrderId=@id AND Status<>'cancelled'",c,tx);q.Parameters.AddWithValue("@id",orderId);await using var r=await q.ExecuteReaderAsync();var ids=new List<Guid>();while(await r.ReadAsync())ids.Add(r.GetGuid(0));await r.CloseAsync();foreach(var id in ids)await DeductOrderItem(c,tx,id,userId);}
    public static async Task MarkOrderWaste(SqlConnection c,SqlTransaction tx,Guid orderId){await using var q=new SqlCommand("UPDATE m SET MovementType='waste',Reason=N'Hao hụt do hủy đơn sau khi pha' FROM dbo.StockMovements m JOIN dbo.OrderItems i ON i.Id=m.ReferenceId WHERE i.OrderId=@order AND m.ReferenceType='order_item' AND m.MovementType='consumption'",c,tx);q.Parameters.AddWithValue("@order",orderId);await q.ExecuteNonQueryAsync();}
}

public record IngredientInput(string Name,string Unit,decimal ReorderLevel,string? Code,string? Category);
public record SupplierInput(string Name,string? Phone,string? Address,string? Note);
public record StockReceiptInput(Guid? SupplierId,string? Note,List<StockReceiptItemInput> Items);
public record StockReceiptItemInput(Guid IngredientId,decimal Quantity,decimal UnitCost);
public record RecipeInput(List<RecipeItemInput> Items);
public record RecipeItemInput(Guid IngredientId,decimal Quantity);
public record InventoryAdjustmentInput(Guid IngredientId,decimal QuantityChange,string Reason);
public record InventoryCountInput(string? Note,List<InventoryCountItemInput> Items);
public record InventoryCountItemInput(Guid IngredientId,decimal ActualQuantity);
